import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"00 · 操作系统导读：一台机器内部在忙什么","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/os/00.md","filePath":"bagu/os/00.md"}'),l={name:"bagu/os/00.md"};function e(p,s,i,r,u,d){return t(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="_00-·-操作系统导读-一台机器内部在忙什么" tabindex="-1">00 · 操作系统导读：一台机器内部在忙什么 <a class="header-anchor" href="#_00-·-操作系统导读-一台机器内部在忙什么" aria-label="Permalink to &quot;00 · 操作系统导读：一台机器内部在忙什么&quot;">​</a></h1><blockquote><p>读完这篇，你要能回答一个问题：<strong>我写的一行代码，机器到底做了什么？</strong></p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>操作系统是一层**&quot;资源中介&quot;**：它把一台机器的三种稀缺资源（CPU、内存、设备）切成小块，分给多个程序，并且保证它们不互相踩。</p><h2 id="生活类比-一家餐厅" tabindex="-1">生活类比：一家餐厅 <a class="header-anchor" href="#生活类比-一家餐厅" aria-label="Permalink to &quot;生活类比：一家餐厅&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作系统</th><th>餐厅</th></tr></thead><tbody><tr><td>CPU</td><td>灶台。只有一个（单核），谁抢到谁能炒</td></tr><tr><td>进程</td><td>一桌客人的订单。有自己的食材、自己的进度、互不干扰</td></tr><tr><td>线程</td><td>同一桌订单里的几道菜。共用一个操作台，但可以同时做</td></tr><tr><td>内存</td><td>操作台。面积有限，摆不下就收进仓库</td></tr><tr><td>磁盘</td><td>后厨仓库。很大，但取东西慢得多</td></tr><tr><td>调度器</td><td>排号叫号的服务员</td></tr><tr><td>系统调用</td><td>客人不能自己进后厨，只能叫服务员</td></tr><tr><td>缺页中断</td><td>客人点了操作台上没有的菜，服务员去仓库取</td></tr></tbody></table><p>这套类比贯穿整个模块。后面所有篇目都用这张表。</p><h2 id="模块地图-5-篇怎么接" tabindex="-1">模块地图：5 篇怎么接 <a class="header-anchor" href="#模块地图-5-篇怎么接" aria-label="Permalink to &quot;模块地图：5 篇怎么接&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-- 用户态：你的程序</span></span>
<span class="line"><span>|     只能算数，只能访问自己的地址</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>|     （唯一合法入口：系统调用，见 05）</span></span>
<span class="line"><span>|           |</span></span>
<span class="line"><span>|           v</span></span>
<span class="line"><span>+-- 内核态：管理员</span></span>
<span class="line"><span>|     · 谁在用 CPU     --&gt;  进程 / 线程     01</span></span>
<span class="line"><span>|     · 地址怎么翻译   --&gt;  虚拟内存        02</span></span>
<span class="line"><span>|     · 谁能同时动     --&gt;  锁 / 调度       03</span></span>
<span class="line"><span>|     · 怎么等设备     --&gt;  IO 模型         04</span></span></code></pre></div><p>五篇不是五个独立话题，是<strong>同一个内核的五个侧面</strong>。它们的接口关系：</p><ul><li><strong>01 进程线程</strong>：定义了&quot;谁&quot;在跑。它是 02/03/04 的<strong>主体</strong>——内存是给进程的，锁是线程抢的，IO 是进程在等。</li><li><strong>02 虚拟内存</strong>：定义了&quot;跑在哪&quot;。它让 01 里的每个进程<strong>以为自己独占一台机器</strong>。</li><li><strong>03 调度同步</strong>：定义了&quot;怎么分&quot;。CPU 分给谁（调度）、内存里的共享数据谁先动（同步）。</li><li><strong>04 IO 模型</strong>：定义了&quot;怎么等&quot;。等设备的时候，CPU 不能干等着——这就把 01 的&quot;阻塞/就绪&quot;和 03 的&quot;调度&quot;接起来了。</li><li><strong>05 内核态</strong>：定义了&quot;怎么进门&quot;。前四篇的所有能力，用户程序都只能通过它来请求。</li></ul><h2 id="一条主线-程序跑起来发生了什么" tabindex="-1">一条主线：程序跑起来发生了什么 <a class="header-anchor" href="#一条主线-程序跑起来发生了什么" aria-label="Permalink to &quot;一条主线：程序跑起来发生了什么&quot;">​</a></h2><p>把五篇串起来，就是这一条线。<strong>建议你先通读一遍这条线，再回去看细节</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 你双击程序</span></span>
<span class="line"><span>   v  内核创建一个进程（01）：分配 PID、地址空间、打开文件表</span></span>
<span class="line"><span>2. 进程被放进就绪队列</span></span>
<span class="line"><span>   v  调度器选中它（03），CPU 开始执行它的指令</span></span>
<span class="line"><span>3. 它要读一个变量</span></span>
<span class="line"><span>   v  CPU 拿到的是虚拟地址（02），查页表翻译成物理地址</span></span>
<span class="line"><span>   v  页表说&quot;这页不在内存里&quot;&gt; 缺页中断 &gt; 从磁盘换入</span></span>
<span class="line"><span>4. 它要读文件</span></span>
<span class="line"><span>   v  用户态不能直接碰磁盘 &gt; 发起系统调用（05）</span></span>
<span class="line"><span>   v  内核把请求交给磁盘，进程进入阻塞态（01）</span></span>
<span class="line"><span>   v  调度器换别的进程上 CPU（03）—— 这就是&quot;并发&quot;的真相</span></span>
<span class="line"><span>5. 磁盘好了，中断把进程唤醒</span></span>
<span class="line"><span>   v  进程回到就绪队列，等下一次被调度</span></span>
<span class="line"><span>6. 两个线程要改同一个计数器</span></span>
<span class="line"><span>   v  用锁互斥（03），或者用 CAS 无锁</span></span></code></pre></div><p><strong>这条线里的每一步，都是一个高频面试题</strong>。学完五篇后回来重读，你会发现每一句都能展开讲三分钟。</p><h2 id="学这个模块的方法" tabindex="-1">学这个模块的方法 <a class="header-anchor" href="#学这个模块的方法" aria-label="Permalink to &quot;学这个模块的方法&quot;">​</a></h2><ol><li><strong>别背概念，盯住&quot;为什么&quot;</strong>。每个机制的存在理由都是&quot;不这么做会出什么事故&quot;。</li><li><strong>一定要动手看</strong>。<code>ps aux</code>、<code>cat /proc/self/maps</code>、<code>ss -tan</code>，看一次比读十遍强。</li><li><strong>画图</strong>。进程状态图、地址翻译图、IO 模型对比图，这三张图必须能默画。</li></ol><h2 id="和其他模块的连接" tabindex="-1">和其他模块的连接 <a class="header-anchor" href="#和其他模块的连接" aria-label="Permalink to &quot;和其他模块的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong>：无（这是最底层的一块，是其他三块的地基）</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/01">分层模型与一次请求的一生</a>：网络请求的收发，本质是进程在等 IO（04）+ 内核协议栈在处理</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/01">复杂度与数组、链表</a>：数组比链表快，根因是 CPU 缓存和内存布局，属于 02 的范畴</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/02">事务与 ACID</a>：数据库的 WAL 日志、刷盘、fsync，全部建立在 04 的 IO 模型上</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/04">锁与死锁</a>：数据库死锁和 OS 死锁是同一套理论</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：操作系统到底在管哪三样东西？为什么是这三样？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>CPU、内存、设备（IO）。</p><p>因为这三样是<strong>稀缺且必须共享</strong>的：一台机器只有一个（或几个）CPU 核，内存容量有限，磁盘和网卡数量有限。而程序有很多个，每个都想独占。</p><p>如果资源无限，就不需要操作系统了——每个程序自己跑自己的就行。<strong>操作系统的全部存在理由，就是&quot;资源不够，得排队分&quot;</strong>。</p></details><p><strong>Q2：为什么用户程序不能直接操作硬件？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>两个原因：</p><ol><li><strong>会互相破坏</strong>。A 程序可以直接改磁盘的某个扇区，就能改掉 B 程序的数据，甚至改掉内核本身。</li><li><strong>会死锁整个系统</strong>。直接操作硬件需要精细的时序和状态机，一个程序写错就可能让设备卡死，而它自己没有权限也没有能力恢复。</li></ol><p>所以硬件被划了一条线：<strong>用户态只能算数，想碰硬件必须&quot;申请&quot;（系统调用）</strong>，由内核检查权限后代为执行。这条线就是 05 篇讲的&quot;特权级&quot;。</p></details><p><strong>Q3：如果一台机器只有一个 CPU 核，还能同时跑 100 个程序吗？怎么做到的？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>能。这叫<strong>并发</strong>，不是并行。</p><p>做法是&quot;快速轮换&quot;：每个程序跑几毫秒，时间片用完就被强制换下来，换下一个。因为切换速度（毫秒级）远快于人感知（百毫秒级），看起来就像同时在跑。</p><p>关键点：<strong>切换是有成本的</strong>（保存寄存器、切换页表、刷 TLB，即&quot;上下文切换&quot;）。所以不是切得越勤越好——切太勤，时间全花在切换上了。这个权衡在 03 篇展开。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;灶台只有一个&quot;只对单核成立</strong>。多核是多个灶台，此时才有真正的&quot;并行&quot;。面试常在这里挖坑：并发 ≠ 并行。</li><li><strong>&quot;操作台&quot;是连续的，内存不是</strong>。物理内存被切成固定大小的&quot;页&quot;，一个进程的页可以散落在任意位置，靠页表拼起来。这是 02 篇的核心。</li><li><strong>餐厅里客人能看见后厨，程序看不见内核</strong>。用户态程序连内核的内存地址都访问不到（会触发段错误），这个隔离比餐厅严格得多。</li><li><strong>&quot;进程 = 一桌订单&quot;这个类比会让人误以为进程之间能共享</strong>。实际上进程的地址空间是<strong>完全隔离</strong>的，共享必须显式申请（共享内存）。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出操作系统管理的三种资源，并解释&quot;为什么资源无限就不需要 OS&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能用餐厅类比，把进程/线程/内存/磁盘/调度/系统调用六个词一次讲对</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能在纸上画出上面那张&quot;5 篇怎么接&quot;的图，并说出每篇之间的接口</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能不看资料口述&quot;程序跑起来发生了什么&quot;那条主线，至少说出 5 个步骤</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释并发和并行的区别，并说出上下文切换的代价</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,30)])])}const h=a(l,[["render",e]]);export{g as __pageData,h as default};
